let g = global.get('gemelo') || {
    estado_actual: { temperatura: null, humedad: null, presion: null, audio: null,
                     persona: false, led: false },
    historial_1h: [],
    alertas_activas: [],
    prediccion_30min: {},
    umbrales: { temperatura: 30, audio: 500 },
    resumen_llm: ''
};
const t = msg.topic || '';
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { /* payload de texto plano (p.ej. alerta) */ }
}

if (t.endsWith('/temperatura') && p && p.temperatura !== undefined) g.estado_actual.temperatura = p.temperatura;
else if (t.endsWith('/humedad') && p && p.humedad !== undefined) g.estado_actual.humedad = p.humedad;
else if (t.endsWith('/presion') && p && p.presion !== undefined) g.estado_actual.presion = p.presion;
else if (t.endsWith('/sensor_extra') && p && p.sensor_extra !== undefined) g.estado_actual.audio = p.sensor_extra;
else if (t.endsWith('/alerta')) {
    const mensaje = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);
    // dedupe: el broker entrega el mismo mensaje 2 veces (suscripciones solapadas)
    const ultima = g.alertas_activas[g.alertas_activas.length - 1];
    if (!(ultima && ultima.mensaje === mensaje && Date.now() - new Date(ultima.ts).getTime() < 5000)) {
        g.alertas_activas.push({ ts: new Date().toISOString(), mensaje: mensaje });
    }
} else if (t.endsWith('/camara/evento')) {
    g._persona_ts = Date.now();
} else if (t.endsWith('/control/led')) {
    g.estado_actual.led = (msg.payload === 'on' || msg.payload === true);
} else if (t.indexOf('/prediccion/') !== -1) {
    const variable = t.split('/').pop();
    if (p && p.valor !== undefined) g.prediccion_30min[variable] = p.valor;
}

// vigencia: alertas de los ultimos 10 min, persona vista hace < 60 s
const hace10min = Date.now() - 10 * 60 * 1000;
g.alertas_activas = g.alertas_activas.filter(a => new Date(a.ts).getTime() > hace10min).slice(-20);
g.estado_actual.persona = !!(g._persona_ts && (Date.now() - g._persona_ts) < 60000);
g.ultimo_update = new Date().toISOString();
global.set('gemelo', g);
return null;

// Convierte el mensaje del sensor a line protocol y lo escribe en InfluxDB
const campo = {
    'temperatura': 'temperatura', 'humedad': 'humedad',
    'presion': 'presion', 'sensor_extra': 'audio'
}[(msg.topic || '').split('/').pop()];
if (!campo) return null;
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
const clave = campo === 'audio' ? 'sensor_extra' : campo;
const v = p ? p[clave] : undefined;
if (typeof v !== 'number' || isNaN(v)) return null;

// dedupe: el broker entrega 2 veces el mismo mensaje por suscripciones solapadas
const ultimo = context.get('t_' + campo) || 0;
if (Date.now() - ultimo < 1000) return null;
context.set('t_' + campo, Date.now());

msg.method = 'POST';
msg.url = 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms';
msg.headers = {
    'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = 'sensores,equipo=equipo01 ' + campo + '=' + v + ' ' + Date.now();
return msg;

// Reenvia una alerta MQTT al webhook del agente n8n (debounce de 120 s)
if (!(msg.topic || '').endsWith('/alerta')) return null;
const ultimo = context.get('ultimo_fwd') || 0;
if (Date.now() - ultimo < 120000) return null;
context.set('ultimo_fwd', Date.now());
return {
    method: 'POST',
    url: 'http://n8n:5678/webhook/evento-critico',
    headers: { 'Content-Type': 'application/json' },
    payload: { alerta: (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload) }
};

// Cada 1 min: agrega el estado actual al historial (maximo 60 registros = 1 h)
let g = global.get('gemelo');
if (!g || g.estado_actual.temperatura === null) return null;
g.historial_1h.push({
    ts: new Date().toISOString(),
    temperatura: g.estado_actual.temperatura,
    humedad: g.estado_actual.humedad,
    presion: g.estado_actual.presion,
    audio: g.estado_actual.audio
});
if (g.historial_1h.length > 60) g.historial_1h = g.historial_1h.slice(-60);
global.set('gemelo', g);
return null;

const g = global.get('gemelo') || {};
const salida = {
    ultimo_update: g.ultimo_update || null,
    estado_actual: g.estado_actual || {},
    historial_1h: g.historial_1h || [],
    alertas_activas: (g.alertas_activas || []).map(a => a.mensaje),
    prediccion_30min: g.prediccion_30min || {},
    umbrales: g.umbrales || {},
    resumen_llm: g.resumen_llm || ''
};
msg.payload = salida;
msg.statusCode = 200;
return msg;

// Ejecuta una accion del agente: llega { herramienta, parametros, razonamiento? }
// Salidas: [ mqtt out, escritura InfluxDB (eventos), respuesta HTTP ]
const b = msg.payload || {};
const h = b.herramienta;
const p = b.parametros || {};
let g = global.get('gemelo') || {};
const lp = (texto) => String(texto).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

let mqttMsg = null, influxMsg = null;
let detalle = '';

if (h === 'activar_actuador') {
    const disp = p.dispositivo || 'led';
    const estado = (p.estado === true || p.estado === 'true' || p.estado === 'on');
    // semantica del LED del proyecto: control/led espera "on"/"off"
    mqttMsg = { topic: 'smarthome/equipo01/control/' + disp, payload: estado ? 'on' : 'off' };
    detalle = 'actuador ' + disp + ' -> ' + (estado ? 'on' : 'off');
} else if (h === 'enviar_notificacion') {
    mqttMsg = { topic: 'smarthome/equipo01/llm/notificacion', payload: String(p.mensaje || '') };
    detalle = 'notificacion: ' + (p.mensaje || '');
} else if (h === 'registrar_evento') {
    detalle = 'evento: ' + (p.descripcion || '');
} else if (h === 'ajustar_umbral') {
    g.umbrales = g.umbrales || {};
    if (p.sensor && p.nuevo_umbral !== undefined) {
        g.umbrales[p.sensor] = Number(p.nuevo_umbral);
        global.set('gemelo', g);
    }
    detalle = 'umbral ' + p.sensor + ' -> ' + p.nuevo_umbral;
} else {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'herramienta desconocida: ' + h };
    return [null, null, msg];
}

// registro del uso de la herramienta en InfluxDB (measurement eventos)
influxMsg = {
    method: 'POST',
    url: 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms',
    headers: { 'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
               'Content-Type': 'text/plain; charset=utf-8' },
    payload: 'eventos,origen=agente herramienta="' + lp(h) + '",detalle="' + lp(detalle) + '" ' + Date.now()
};

msg.statusCode = 200;
msg.payload = { ok: true, ejecutado: h, detalle: detalle };
return [mqttMsg, influxMsg, msg];

// Registra el ciclo de razonamiento del agente.
// Llega { razonamiento, acciones: [...] }
// Salidas: [ mqtt llm/decision, escritura InfluxDB (agente), respuesta HTTP ]
const b = msg.payload || {};
const razonamiento = String(b.razonamiento || '');
const acciones = Array.isArray(b.acciones) ? b.acciones : [];
const lp = (texto) => String(texto).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

let g = global.get('gemelo') || {};
g.resumen_llm = razonamiento;
global.set('gemelo', g);

const mqttMsg = {
    topic: 'smarthome/equipo01/llm/decision',
    payload: JSON.stringify({ razonamiento: razonamiento, acciones: acciones })
};
const resumenAcc = acciones.map(a => a.herramienta || '?').join(',') || 'ninguna';
const influxMsg = {
    method: 'POST',
    url: 'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=ms',
    headers: { 'Authorization': 'Token ' + env.get('INFLUXDB_TOKEN'),
               'Content-Type': 'text/plain; charset=utf-8' },
    payload: 'agente,origen=n8n razonamiento="' + lp(razonamiento) + '",acciones="' + lp(resumenAcc)
             + '",n_acciones=' + acciones.length + 'i ' + Date.now()
};

msg.statusCode = 200;
msg.payload = { ok: true };
return [mqttMsg, influxMsg, msg];

// Webhook de la alerta de Grafana -> publica alerta MQTT
// Salidas: [ mqtt alerta, respuesta HTTP ]
const b = msg.payload || {};
const titulo = b.title || (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.alertname) || 'Alerta Grafana';
const mqttMsg = {
    topic: 'smarthome/equipo01/alerta',
    payload: JSON.stringify({ tipo: 'grafana', mensaje: titulo })
};
msg.statusCode = 200;
msg.payload = { ok: true };
return [mqttMsg, msg];
